import re, sys

class Cell:
    __slots__=('ch','fg','bg','attrs')
    def __init__(self):
        self.ch=' '; self.fg=None; self.bg=None; self.attrs=frozenset()

class Term:
    def __init__(self, rows=30, cols=100):
        self.rows=rows; self.cols=cols
        self.grid=[[Cell() for _ in range(cols)] for _ in range(rows)]
        self.r=0; self.c=0
        self.fg=None; self.bg=None; self.attrs=set()

    def clear(self):
        self.grid=[[Cell() for _ in range(self.cols)] for _ in range(self.rows)]

    def put(self, ch):
        if self.c>=self.cols:
            self.c=0; self.r+=1
        if self.r>=self.rows: 
            # scroll
            self.grid.pop(0); self.grid.append([Cell() for _ in range(self.cols)]); self.r=self.rows-1
        cell=self.grid[self.r][self.c]
        cell.ch=ch; cell.fg=self.fg; cell.bg=self.bg; cell.attrs=frozenset(self.attrs)
        self.c+=1

    def sgr(self, params):
        if not params: params=[0]
        i=0
        while i < len(params):
            p=params[i]
            if p==0: self.fg=None; self.bg=None; self.attrs=set()
            elif p==1: self.attrs.add('bold')
            elif p==2: self.attrs.add('dim')
            elif p==3: self.attrs.add('italic')
            elif p==4: self.attrs.add('underline')
            elif p==5: self.attrs.add('blink')
            elif p==7: self.attrs.add('reverse')
            elif p==8: self.attrs.add('hidden')
            elif p==9: self.attrs.add('strike')
            elif p==21: self.attrs.discard('bold')
            elif p==22: self.attrs.discard('bold'); self.attrs.discard('dim')
            elif p==23: self.attrs.discard('italic')
            elif p==24: self.attrs.discard('underline')
            elif p==25: self.attrs.discard('blink')
            elif p==27: self.attrs.discard('reverse')
            elif p==29: self.attrs.discard('strike')
            elif 30<=p<=37: self.fg=p-30
            elif p==38:
                if i+1<len(params) and params[i+1]==5: self.fg=('256',params[i+2]); i+=2
                elif i+1<len(params) and params[i+1]==2: self.fg=('rgb',params[i+2],params[i+3],params[i+4]); i+=4
            elif p==39: self.fg=None
            elif 40<=p<=47: self.bg=p-40
            elif p==48:
                if i+1<len(params) and params[i+1]==5: self.bg=('256',params[i+2]); i+=2
                elif i+1<len(params) and params[i+1]==2: self.bg=('rgb',params[i+2],params[i+3],params[i+4]); i+=4
            elif p==49: self.bg=None
            elif 90<=p<=97: self.fg=p-90+8
            elif 100<=p<=107: self.bg=p-100+8
            i+=1

    def feed(self, data):
        if isinstance(data, bytes): data=data.decode('utf-8', 'replace')
        i=0; n=len(data)
        while i<n:
            ch=data[i]
            if ch=='\x1b':
                if i+1<n and data[i+1]=='[':
                    j=i+2
                    while j<n and not (0x40 <= ord(data[j]) <= 0x7e):
                        j+=1
                    if j>=n: break
                    seq=data[i+2:j]; final=data[j]
                    priv = seq.startswith('?')
                    body = seq[1:] if priv else seq
                    parts=[x for x in body.split(';')]
                    nums=[]
                    for x in parts:
                        try: nums.append(int(x))
                        except: nums.append(None)
                    def g(k, d=1):
                        if k<len(nums) and nums[k] is not None: return nums[k]
                        return d
                    if final=='H' or final=='f':
                        self.r=g(0,1)-1; self.c=g(1,1)-1
                    elif final=='J':
                        m=g(0,0)
                        if m==2: self.clear()
                        elif m==0:
                            for cc in range(self.c, self.cols): self.grid[self.r][cc]=Cell()
                            for rr in range(self.r+1, self.rows): self.grid[rr]=[Cell() for _ in range(self.cols)]
                        elif m==1:
                            for rr in range(0,self.r): self.grid[rr]=[Cell() for _ in range(self.cols)]
                            for cc in range(0,self.c+1): self.grid[self.r][cc]=Cell()
                    elif final=='K':
                        m=g(0,0)
                        if m==0:
                            for cc in range(self.c,self.cols): self.grid[self.r][cc]=Cell()
                        elif m==1:
                            for cc in range(0,self.c+1): self.grid[self.r][cc]=Cell()
                        else:
                            self.grid[self.r]=[Cell() for _ in range(self.cols)]
                    elif final=='m' and not priv:
                        self.sgr([x if x is not None else 0 for x in nums])
                    elif final=='A': self.r=max(0,self.r-g(0,1))
                    elif final=='B': self.r=min(self.rows-1,self.r+g(0,1))
                    elif final=='C': self.c=min(self.cols-1,self.c+g(0,1))
                    elif final=='D': self.c=max(0,self.c-g(0,1))
                    elif final=='d': self.r=g(0,1)-1
                    elif final=='G': self.c=g(0,1)-1
                    i=j+1; continue
                elif i+1<n and data[i+1]==']':
                    j=data.find('\x07', i)
                    j2=data.find('\x1b\\', i)
                    if j==-1 and j2==-1: break
                    end = min([x for x in (j,j2) if x!=-1])
                    i = end + (1 if end==j else 2); continue
                elif i+1<n and data[i+1] in '()#':
                    i+=3; continue
                else:
                    i+=2; continue
            elif ch=='\r': self.c=0; i+=1; continue
            elif ch=='\n':
                self.r+=1
                if self.r>=self.rows:
                    self.grid.pop(0); self.grid.append([Cell() for _ in range(self.cols)]); self.r=self.rows-1
                i+=1; continue
            elif ch=='\b': self.c=max(0,self.c-1); i+=1; continue
            elif ch=='\t': self.c=min(self.cols-1,(self.c//8+1)*8); i+=1; continue
            elif ch=='\x07': i+=1; continue
            elif ord(ch)<32: i+=1; continue
            else:
                self.put(ch); i+=1; continue
        return self

    def text(self):
        return '\n'.join(''.join(cell.ch for cell in row).rstrip() for row in self.grid)

    def styled(self):
        out=[]
        for row in self.grid:
            line=[]
            for cell in row:
                a=''.join(sorted(x[0] for x in cell.attrs))
                line.append('%s|%s|%s|%s' % (cell.ch, cell.fg, cell.bg, a))
            out.append(' '.join(line))
        return '\n'.join(out)

    def dump_styles(self):
        # compact: runs of same style
        out=[]
        for ri,row in enumerate(self.grid):
            runs=[]; cur=None; start=0; txt=''
            for ci,cell in enumerate(row):
                key=(cell.fg,cell.bg,tuple(sorted(cell.attrs)))
                if key!=cur:
                    if cur is not None and txt.strip(): runs.append((start,txt,cur))
                    cur=key; start=ci; txt=cell.ch
                else: txt+=cell.ch
            if cur is not None and txt.strip(): runs.append((start,txt,cur))
            if runs: out.append('%2d: %s' % (ri, ' || '.join('%d:%r %s' % (s,t,c) for s,t,c in runs)))
        return '\n'.join(out)

def render(raw, rows=30, cols=100):
    t=Term(rows,cols); t.feed(raw); return t
