import os, pty, sys, time, select, fcntl, termios, struct, signal
sys.path.insert(0,'/tmp/rec')
from term import Term

class Session:
    def __init__(self, args, rows=30, cols=100, exe='./executable', env_extra=None, settle=0.6):
        self.rows=rows; self.cols=cols
        self.pid, self.fd = pty.fork()
        if self.pid==0:
            env=dict(os.environ); env['TERM']='xterm-256color'
            env['COLUMNS']=str(cols); env['LINES']=str(rows)
            if env_extra: env.update(env_extra)
            os.execvpe(exe, [exe]+list(args), env)
        fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0,0))
        self.term=Term(rows,cols)
        self.raw=b''
        self.alive=True
        self.pump(settle)
    def pump(self, t=0.25):
        end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([self.fd],[],[],0.02)
            if r:
                try: d=os.read(self.fd,65536)
                except OSError: self.alive=False; break
                if not d: self.alive=False; break
                self.raw+=d; self.term.feed(d)
        return self.term
    def send(self, s, wait=0.06):
        os.write(self.fd, s if isinstance(s,bytes) else s.encode())
        self.pump(wait)
    def lines(self):
        return self.term.text().split('\n')
    def show(self):
        print(self.term.text())
    def close(self):
        try: os.kill(self.pid, signal.SIGKILL)
        except Exception: pass
        try: os.waitpid(self.pid,0)
        except Exception: pass
